/// Vertical metrics and glyph widths for one core font.
#[derive(Debug, Clone, Copy)]
pub(crate) struct Metrics {
    /// Baseline to the top of the tallest glyph, in 1/1000 em.
    pub ascent: i16,
    /// Baseline down to the lowest descender, as a positive number of 1/1000 em.
    pub descent: i16,
    /// Per-code glyph widths in 1/1000 em.
    pub widths: &'static Widths,
}

/// Metrics for `font`.
pub(crate) fn metrics(font: StandardFont) -> Metrics {
    let widths: &'static Widths = match font {
        StandardFont::Helvetica => &W_HELVETICA,
        StandardFont::HelveticaBold => &W_HELVETICA_BOLD,
        StandardFont::HelveticaOblique => &W_HELVETICA_OBLIQUE,
        StandardFont::HelveticaBoldOblique => &W_HELVETICA_BOLDOBLIQUE,
        StandardFont::TimesRoman => &W_TIMES_ROMAN,
        StandardFont::TimesBold => &W_TIMES_BOLD,
        StandardFont::TimesItalic => &W_TIMES_ITALIC,
        StandardFont::TimesBoldItalic => &W_TIMES_BOLDITALIC,
        StandardFont::Courier => &W_COURIER,
        StandardFont::CourierBold => &W_COURIER_BOLD,
        StandardFont::CourierOblique => &W_COURIER_OBLIQUE,
        StandardFont::CourierBoldOblique => &W_COURIER_BOLDOBLIQUE,
    };
    let (ascent, descent) = match font {
        StandardFont::Helvetica
        | StandardFont::HelveticaBold
        | StandardFont::HelveticaOblique
        | StandardFont::HelveticaBoldOblique => (718, 207),
        StandardFont::TimesRoman
        | StandardFont::TimesBold
        | StandardFont::TimesItalic
        | StandardFont::TimesBoldItalic => (683, 217),
        StandardFont::Courier
        | StandardFont::CourierBold
        | StandardFont::CourierOblique
        | StandardFont::CourierBoldOblique => (627, 194),
    };
    Metrics {
        ascent,
        descent,
        widths,
    }
}
